describe('Dropdown Close on Escape Key Press', () => {
  beforeEach(() => {
    cy.visit('/dropdown');
  });

  it('should close dropdown when Escape key is pressed while focused', () => {
    // Intercept the dropdown open API call
    cy.intercept('GET', '/api/dropdown/open').as('openDropdown');

    // Click the dropdown trigger element
    cy.get('[data-testid="dropdown-trigger"]').click();

    // Verify dropdown is visible
    cy.get('[data-testid="dropdown-menu"]').should('be.visible');

    // Verify dropdown content is displayed
    cy.get('[data-testid="dropdown-item"]').should('contain', 'Item 1');

    // Press Escape key
    cy.get('[data-testid="dropdown-menu"]').type('{esc}');

    // Verify dropdown is closed
    cy.get('[data-testid="dropdown-menu"]').should('not.exist');

    // Verify dropdown close API was called
    cy.wait('@openDropdown').then((interception) => {
      expect(interception.response.statusCode).to.equal(200);
    });

    // Verify dropdown close button is visible
    cy.get('[data-testid="dropdown-close-btn"]').should('be.visible');
  });

  it('should not close dropdown when Escape key is pressed outside of dropdown', () => {
    // Intercept the dropdown open API call
    cy.intercept('GET', '/api/dropdown/open').as('openDropdown');

    // Click the dropdown trigger element
    cy.get('[data-testid="dropdown-trigger"]').click();

    // Verify dropdown is visible
    cy.get('[data-testid="dropdown-menu"]').should('be.visible');

    // Verify dropdown content is displayed
    cy.get('[data-testid="dropdown-item"]').should('contain', 'Item 1');

    // Press Escape key
    cy.get('[data-testid="dropdown-menu"]').type('{esc}');

    // Verify dropdown remains open
    cy.get('[data-testid="dropdown-menu"]').should('be.visible');

    // Verify dropdown close button is still visible
    cy.get('[data-testid="dropdown-close-btn"]').should('be.visible');

    // Verify Escape key does not trigger close outside of dropdown
    cy.get('[data-testid="main-content"]').type('{esc}');

    // Verify main content is still visible
    cy.get('[data-testid="main-content"]').should('be.visible');
  });
});
